-- ROLLBACK (by slug): delete from cpl_memory_log where memory_id in (select id from cpl_memory where slug in ('riverside-plain-2-0-siblings-kept-s659','cq-twin-wrong-content-44469-s659','d-identity-drops-dropped-honors-s659')); delete from cpl_memory where slug in ('riverside-plain-2-0-siblings-kept-s659','cq-twin-wrong-content-44469-s659','d-identity-drops-dropped-honors-s659');
-- No row is superseded; every row is proposed.
insert into cpl_memory (slug,kind,title,summary,tags,status,source,verified_by,verified_at,author,event_date) values
('riverside-plain-2-0-siblings-kept-s659','question','Plain siblings of a 2.0 ADT keep records read from the successor''s page','S659, #3365: Riverside City''s 30578, 32692, 32745 and 33829 read page_claimed because the catalog prints only each 2.0 successor''s page, as d-ge-page-one-owner-s653 rules. Their filed records, read from those pages, pass and keep_no_read keeps them. Statewide 99 plain/2.0 pairs share one filed page under S648. Sharing on the GE path failed four pinned checks: for Sam or COBIx.',array['program-requirements','question'],'proposed','S659 checkpoint; docs/session_660_handoff.md, #3365 and #3366',null,null,'SkyWhimbrel (S659)',date '2026-11-15'),
('cq-twin-wrong-content-44469-s659','fact','A curriQunet title twin can print another program''s list','S659, page read 43726316036: Riverside City''s 44469 (Native American and Indigenous Studies AA-T) has its own page at 6118/5869. cq_distinct kept its title twin 6117/5875, which prints 44469''s heading over the African American Studies list, so the capture refused it. The filed record from 5869 stays. 37474 Kinesiology AA-T has no page among those read.',array['program-requirements','fact'],'proposed','S659 checkpoint; docs/session_660_handoff.md, #3365 and #3366',null,null,'SkyWhimbrel (S659)',date '2026-11-15'),
('d-identity-drops-dropped-honors-s659','decision','An identity title drops an Honors marker only where curation dropped it','S659, #3366: the display build takes an identity''s title from the minted common_title, which kept ''Media & Information Literacy (Honors)'' for LIBR M1040 after S652''s retitle. shown_title() uses the curated title only where it is the minted one minus an Honors marker: 1 of 19,568 ids. The other 2,288 minted/curated differences stay as built.',array['program-requirements','decision'],'proposed','S659 checkpoint; docs/session_660_handoff.md, #3365 and #3366',null,null,'SkyWhimbrel (S659)',date '2026-11-15')
on conflict (slug) do nothing;
insert into public.cpl_memory_log (memory_id, actor, action, note, after)
select id, 'SkyWhimbrel (S659)', 'create', 'S659 checkpoint (2026-11-15)', to_jsonb(m)
from public.cpl_memory m where m.slug in ('riverside-plain-2-0-siblings-kept-s659','cq-twin-wrong-content-44469-s659','d-identity-drops-dropped-honors-s659')
  and not exists (select 1 from public.cpl_memory_log l where l.memory_id = m.id and l.action = 'create');
select m.slug, length(m.summary) as summary_chars, count(l.id) filter (where l.action = 'create') as creates
from public.cpl_memory m left join public.cpl_memory_log l on l.memory_id = m.id
where m.slug in ('riverside-plain-2-0-siblings-kept-s659','cq-twin-wrong-content-44469-s659','d-identity-drops-dropped-honors-s659') group by m.slug, m.summary order by m.slug;
